import{verifiedOwnedFreeSpans}from './owned-free-space.js';
// Long erased runs only; protect every aligned ROM pointer target and its vicinity.
export function erasedROMSpans(bytes){const refs=[],v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);for(let at=0;at+4<=bytes.length;at+=4){const n=v.getUint32(at,true)-0x08000000;if(n>=512&&n<bytes.length)refs.push(n);}refs.sort((a,b)=>a-b);const owned=verifiedOwnedFreeSpans(bytes),spans=[...owned];for(let at=512;at<bytes.length-40;){if(bytes[at]!==255){at++;continue;}const begin=at;while(at<bytes.length-40&&bytes[at]===255)at++;if(at-begin<65536)continue;if(owned.some(s=>begin>=s.start&&at<=s.end))continue;let cursor=(begin+3)&~3;for(const n of refs){if(n<begin)continue;if(n>=at)break;const stop=Math.max(cursor,n-256);if(stop-cursor>=4096)spans.push({start:cursor,end:stop});cursor=Math.max(cursor,(n+259)&~3);}if(at-16-cursor>=4096)spans.push({start:cursor,end:at-16});}const merged=[];for(const s of spans.sort((a,b)=>a.start-b.start)){const last=merged.at(-1);if(last&&s.start<=last.end)last.end=Math.max(last.end,s.end);else merged.push({...s});}return merged;}

